package com.loanops.fincompass.api;import com.loanops.fincompass.opportunity.*;import org.springframework.web.bind.annotation.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import java.util.*;import static com.loanops.fincompass.api.TwinController.DEMO_OWNER;import static com.loanops.fincompass.opportunity.OpportunityModels.*;
@RestController @RequestMapping("/api/v1/opportunities") @ConditionalOnProperty(name="fincompass.demo.enabled",havingValue="true") public class OpportunityController{private final OpportunityService service;public OpportunityController(OpportunityService service){this.service=service;}@GetMapping public List<Event> opportunities(){var active=service.active(DEMO_OWNER);return active.isEmpty()?service.detect(DEMO_OWNER):active;}}
